import{_ as s,o as n,c as e,N as l}from"./chunks/framework.CM5G1ysn.js";const g=JSON.parse('{"title":"Spring 事务边界：回滚、传播与代理自调用","description":"从连续写入两张表出发，理解 Spring 事务代理如何决定提交与回滚，以及 REQUIRED、REQUIRES_NEW 和自调用的边界。","frontmatter":{"title":"Spring 事务边界：回滚、传播与代理自调用","date":"2026-11-06T00:00:00.000Z","description":"从连续写入两张表出发，理解 Spring 事务代理如何决定提交与回滚，以及 REQUIRED、REQUIRES_NEW 和自调用的边界。","category":"Java 后端","tags":["Spring","Transactional","事务","Java"],"folder":"java/highlights"},"headers":[{"level":2,"title":"代理包住的，才是声明式事务边界","slug":"代理包住的才是声明式事务边界","link":"#代理包住的才是声明式事务边界","children":[]},{"level":2,"title":"异常类型和传播路径决定回滚结果","slug":"异常类型和传播路径决定回滚结果","link":"#异常类型和传播路径决定回滚结果","children":[]},{"level":2,"title":"传播行为描述的是如何使用已有事务","slug":"传播行为描述的是如何使用已有事务","link":"#传播行为描述的是如何使用已有事务","children":[]},{"level":2,"title":"同一个对象中的自调用不会开启新的代理边界","slug":"同一个对象中的自调用不会开启新的代理边界","link":"#同一个对象中的自调用不会开启新的代理边界","children":[]},{"level":2,"title":"把事务边界与业务成功条件对齐","slug":"把事务边界与业务成功条件对齐","link":"#把事务边界与业务成功条件对齐","children":[]},{"level":2,"title":"参考与来源","slug":"参考与来源","link":"#参考与来源","children":[]}],"relativePath":"posts/spring-transaction-boundaries.md","filePath":"posts/spring-transaction-boundaries.md"}'),t={name:"posts/spring-transaction-boundaries.md"};function o(p,a,r,c,i,d){return n(),e("div",null,[...a[0]||(a[0]=[l(`<h1 id="spring-事务边界回滚传播与代理自调用" tabindex="-1">Spring 事务边界：回滚、传播与代理自调用 <a class="header-anchor" href="#spring-事务边界回滚传播与代理自调用" aria-label="Permalink to &quot;Spring 事务边界：回滚、传播与代理自调用&quot;">​</a></h1><p>创建一个项目时，可能既要插入项目记录，又要把创建者加入成员表。如果第二步失败，第一步也应撤销。<code>@Transactional</code> 可以表达这个要求，但判断它是否生效，不能只看方法上有没有注解，还要看调用有没有经过代理、哪些操作加入了事务，以及异常如何离开方法。</p><p>本文讨论常见的 Spring 命令式事务、代理模式和单数据源场景。代码均为说明边界的示意片段，省略依赖注入、实体及 Mapper 定义。</p><h2 id="代理包住的才是声明式事务边界" tabindex="-1">代理包住的，才是声明式事务边界 <a class="header-anchor" href="#代理包住的才是声明式事务边界" aria-label="Permalink to &quot;代理包住的，才是声明式事务边界&quot;">​</a></h2><p>可以先把调用理解为三层：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>Controller 调用 Spring 管理的 Service</span></span>
<span class="line"><span>    → 事务代理按配置开启或加入事务</span></span>
<span class="line"><span>    → Service 执行业务和数据库操作</span></span>
<span class="line"><span>    → 代理根据返回结果与回滚规则提交或回滚</span></span></code></pre></div><div class="language-java"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">@</span><span style="color:#D73A49;">Transactional</span></span>
<span class="line"><span style="color:#D73A49;">public</span><span style="color:#D73A49;"> void</span><span style="color:#6F42C1;"> createProject</span><span style="color:#24292E;">(CreateCommand command) {</span></span>
<span class="line"><span style="color:#24292E;">    projectMapper.</span><span style="color:#6F42C1;">insert</span><span style="color:#24292E;">(</span><span style="color:#6F42C1;">buildProject</span><span style="color:#24292E;">(command));</span></span>
<span class="line"><span style="color:#24292E;">    memberMapper.</span><span style="color:#6F42C1;">insert</span><span style="color:#24292E;">(</span><span style="color:#6F42C1;">buildOwnerMember</span><span style="color:#24292E;">(command));</span></span>
<span class="line"><span style="color:#24292E;">}</span></span></code></pre></div><p>这段设计要成立，两个 Mapper 必须使用参与该事务的数据访问资源。给一个方法加注解，不会自动把另一个数据源、Kafka 消息或远程 HTTP 调用变成同一笔可回滚操作。事务范围应围绕需要共同成功的数据库修改设计。</p><h2 id="异常类型和传播路径决定回滚结果" tabindex="-1">异常类型和传播路径决定回滚结果 <a class="header-anchor" href="#异常类型和传播路径决定回滚结果" aria-label="Permalink to &quot;异常类型和传播路径决定回滚结果&quot;">​</a></h2><p>在未修改默认回滚规则时，<code>RuntimeException</code> 和 <code>Error</code> 会触发回滚，受检异常默认不会。确实需要让某类受检异常导致回滚时，可以显式声明：</p><div class="language-java"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">@</span><span style="color:#D73A49;">Transactional</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">rollbackFor</span><span style="color:#D73A49;"> =</span><span style="color:#24292E;"> ImportException.class)</span></span>
<span class="line"><span style="color:#D73A49;">public</span><span style="color:#D73A49;"> void</span><span style="color:#6F42C1;"> importRecords</span><span style="color:#24292E;">() throws ImportException {</span></span>
<span class="line"><span style="color:#6A737D;">    // 写入数据库；校验失败时向外抛出 ImportException</span></span>
<span class="line"><span style="color:#24292E;">}</span></span></code></pre></div><p>另一个容易混淆的地方是 <code>catch</code>。如果方法把异常吞掉，正常返回，且事务此前没有被标记为仅回滚，代理通常会按成功路径提交。记录一条错误日志并不等于要求事务回滚。</p><p>但“捕获异常就一定能提交”同样不成立。假设内部方法通过代理加入同一事务，并已把共享事务标记为 <code>rollback-only</code>，外层即使捕获异常，提交时仍可能得到 <code>UnexpectedRollbackException</code>。应结合事务是否已经被标记回滚判断，不能只看最后有没有异常向外抛。</p><p>业务层可以把异常交给统一异常处理器生成响应；事务代理通常先处理事务结果，再由上层将异常转换成 HTTP 响应。返回一个表示失败的普通对象，则不必然触发回滚。</p><h2 id="传播行为描述的是如何使用已有事务" tabindex="-1">传播行为描述的是如何使用已有事务 <a class="header-anchor" href="#传播行为描述的是如何使用已有事务" aria-label="Permalink to &quot;传播行为描述的是如何使用已有事务&quot;">​</a></h2><p>传播行为和隔离级别回答不同问题：前者关心调用链如何组织事务，后者关心并发事务之间的数据可见性与隔离。</p><table tabindex="0"><thead><tr><th>传播行为</th><th>当前存在事务时</th><th>当前不存在事务时</th></tr></thead><tbody><tr><td><code>REQUIRED</code>，默认</td><td>加入已有事务</td><td>新建事务</td></tr><tr><td><code>REQUIRES_NEW</code></td><td>挂起外层，开启独立事务</td><td>新建事务</td></tr><tr><td><code>MANDATORY</code></td><td>加入已有事务</td><td>抛出异常</td></tr><tr><td><code>NOT_SUPPORTED</code></td><td>挂起外层，以非事务方式执行</td><td>以非事务方式执行</td></tr></tbody></table><p>例如，写入“待发送事件”的方法如果必须和主业务共同提交，可以通过 <code>MANDATORY</code> 明确约束调用方。它表达的是“必须已有事务”，而不是悄悄替调用方新开一笔。</p><p>独立的审计记录可能适合 <code>REQUIRES_NEW</code>：内部事务一旦提交，外层随后回滚不会撤销它。但它不保证异常不会影响外层；内部异常若继续向外传播，仍可能触发外层的回滚规则。使用这种传播方式还需考虑额外连接需求，不能把它当成不付成本的隔离开关。</p><p>尤其不要为了“解耦”就提前提交一条成功通知：主业务之后可能回滚，通知却已经存在。是否独立提交，首先是业务语义问题。</p><h2 id="同一个对象中的自调用不会开启新的代理边界" tabindex="-1">同一个对象中的自调用不会开启新的代理边界 <a class="header-anchor" href="#同一个对象中的自调用不会开启新的代理边界" aria-label="Permalink to &quot;同一个对象中的自调用不会开启新的代理边界&quot;">​</a></h2><p>在默认代理模式下，下面的调用没有重新经过 Spring 代理：</p><div class="language-java"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">public</span><span style="color:#D73A49;"> void</span><span style="color:#6F42C1;"> register</span><span style="color:#24292E;">() {</span></span>
<span class="line"><span style="color:#005CC5;">    this</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">saveAccount</span><span style="color:#24292E;">();</span></span>
<span class="line"><span style="color:#24292E;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">@</span><span style="color:#D73A49;">Transactional</span></span>
<span class="line"><span style="color:#D73A49;">public</span><span style="color:#D73A49;"> void</span><span style="color:#6F42C1;"> saveAccount</span><span style="color:#24292E;">() {</span></span>
<span class="line"><span style="color:#24292E;">    accountMapper.</span><span style="color:#6F42C1;">insert</span><span style="color:#24292E;">(</span><span style="color:#6F42C1;">buildAccount</span><span style="color:#24292E;">());</span></span>
<span class="line"><span style="color:#24292E;">}</span></span></code></pre></div><p>如果外部调用的是未声明事务的 <code>register()</code>，不能指望内部 <code>saveAccount()</code> 上的注解单独建立事务。若外层本身已有事务，内部操作仍可能参与已有事务；问题是内部注解要求的新边界没有被应用，例如 <code>REQUIRES_NEW</code> 不会仅凭这次自调用生效。</p><p>一种清晰的做法是把需要独立事务语义的方法放入另一个 Spring Bean，由调用方通过注入后的对象调用。也可以在适合的场景使用 <code>TransactionTemplate</code> 显式组织边界。不要通过手动 <code>new</code> Service 来绕开容器，再期待声明式事务继续工作。</p><h2 id="把事务边界与业务成功条件对齐" tabindex="-1">把事务边界与业务成功条件对齐 <a class="header-anchor" href="#把事务边界与业务成功条件对齐" aria-label="Permalink to &quot;把事务边界与业务成功条件对齐&quot;">​</a></h2><p>设计入口时，可以先用一句话写清楚“这次成功必须同时留下哪些数据”。例如项目和创建者成员记录需要共同存在，就由一个 Service 方法组织它们；展示页的多个互不相关查询，则不必因为位于同一个接口里就强行建立很长的写事务。</p><p>事务中的远程调用和大量文件处理也会延长连接、锁等资源的占用时间。若把后续通知移出主事务，就需要同时说明失败后如何恢复，不能只移动一行调用便认为一致性问题已经解决。</p><p>排查时沿实际调用链确认三个事实：事务入口是否经过代理，数据库操作是否加入预期事务，以及失败时应用了什么回滚规则。它们比反复补注解更能解释提交结果。</p><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><p>本文整理自个人项目学习笔记，对事务代理、异常回滚和传播行为补充了适用边界。</p><ul><li><a href="https://docs.spring.io/spring-framework/reference/data-access/transaction/declarative/annotations.html" target="_blank" rel="noreferrer">Spring：使用 @Transactional，含代理模式与自调用说明</a></li><li><a href="https://docs.spring.io/spring-framework/reference/data-access/transaction/declarative/rolling-back.html" target="_blank" rel="noreferrer">Spring：声明式事务的回滚规则</a></li><li><a href="https://docs.spring.io/spring-framework/reference/data-access/transaction/declarative/tx-propagation.html" target="_blank" rel="noreferrer">Spring：事务传播与独立事务的资源需求</a></li></ul>`,32)])])}const y=s(t,[["render",o]]);export{g as __pageData,y as default};
